    raise argparse.ArgumentTypeError(
        f"--limit 必须是 1 至 {MAX_LIMIT} 的正整数，收到: {value!r}"
    )
if number > MAX_LIMIT:
    raise argparse.ArgumentTypeError(
        f"--limit 不能超过单次返回条数上限 {MAX_LIMIT}，收到: {value!r}"
    )
return number

